     // Last down-candle at or just before the swing low: candidate bullish order block.\n        int k = close[len] < open[len] ? len : close[len + 1] < open[len + 1] ? len + 1 : close[len + 2] < open[len + 2] ? len + 2 : len\n        lowObTop := obRangeInput == \"Body\" ? math.max(open[k], close[k]) : high[k]\n        lowObBot := low[k]\n        lowObBar := bar_index - k\n\n    bool bullBos = false\n    bool bullChoch = false\n    bool bearBos = false\n    bool bearChoch = false\n    bool sweepHigh = false\n    bool sweepLow = false\n\n    if barstate.isconfirmed\n        // Bullish break: first bar that trades/closes beyond the unbroken swing high.\n        if not highBroken and not na(lastHigh) and (useClose ? close > lastHigh : high > lastHigh)\n            highBroken := true\n            bullChoch  := trend != 1\n            bullBos    := not bullChoch\n            trend      := 1\n            if show\n                line.new(lastHighBar, lastHigh, bar_index, lastHigh, color = bullColorInput, style = dashed ? line.style_dashed : line.style_solid, width = 1)\n                label.new(math.round((lastHighBar + bar_index) / 2), lastHigh, bullChoch ? \"CHoCH\" : \"BOS\", style = label.style_label_down, color = color.new(bullColorInput, 100), textcolor = bullColorInput, size = dashed ? size.tiny : size.small)\n            if makeObs and showObInput and not na(lowObBar)\n                addZone(bullObs, lowObBar, lowObTop, lowObBot, true, bullColorInput, \"OB\", obCountInput)\n                lowObBar := na\n        // Bearish break.\n        if not lowBroken and not na(lastLow) and (useClose ? close < lastLow : low < lastLow)\n            lowBroken := true\n            bearChoch := trend != -1\n            bearBos   := not bearChoch\n            trend     := -1\n            if show\n                line.new(lastLowBar, lastLow, bar_index, lastLow, color = bearColorInput, style = dashed ? line.style_dashed : line.style_solid, width = 1)\n                label.new(math.round((lastLowBar + bar_index) / 2), lastLow, bearChoch ? \"CHoCH\" : \"BOS\", style = label.style_label_up, color = color.new(bearColorInput, 100), textcolor = bearColorInput, size = dashed ? size.tiny : size.small)\n            if makeObs and showObInput and not na(highObBar)\n                addZone(bearObs, highObBar, highObTop, highObBot, false, bearColorInput, \"OB\", obCountInput)\n                highObBar := na\n        // Liquidity sweep: wick through an unbroken swing, close back inside. One mark per swing.\n        if markLiq and showSweepInput\n            if not highBroken and not highSwept and not na(lastHigh) and high > lastHigh and close < lastHigh\n                highSwept := true\n                sweepHigh := true\n                label.new(bar_index, high, \"Sweep\", style = label.style_label_down, color = color.new(liqColorInput, 100), textcolor = liqColorInput, size = size.tiny)\n            if not lowBroken and not lowSwept and not na(lastLow) and low < lastLow and close > lastLow\n                lowSwept := true\n                sweepLow := true\n                label.new(bar_index, low, \"Sweep\", style = label.style_label_up, color = color.new(liqColorInput, 100), textcolor = liqColorInput, size = size.tiny)\n\n    [bullBos, bullChoch, bearBos, bearChoch, trend, sweepHigh, sweepLow, eqHigh, eqLow]\n\n// ---------- Calculations ----------\n[sBullBos, sBullChoch, sBearBos, sBearChoch, swingTrend, sweepHigh, sweepLow, eqHigh, eqLow] = structure(swingLenInput, true, false, true, true)\n[iBullBos, iBullChoch, iBearBos, iBearChoch, internalTrend, iSweepH, iSweepL, iEqH, iEqL] = structure(internalLenInput, showInternalInput, true, false, false)\n\n// Fair value gaps: three-candle imbalance, confirmed on the close of the third candle.\nbool bullFvg = false\nbool bearFvg = false\nif barstate.isconfirmed and showFvgInput\n    if low > high[2] and (low - high[2]) >= atr * fvgMinAtrInput\n        bullFvg := true\n        addZone(bullFvgs, bar_index - 1, low, high[2], true, bullColorInput, \"FVG\", fvgCountInput)\n    if high < low[2] and (low[2] - high) >= atr * fvgMinAtrInput\n        bearFvg := true\n        addZone(bearFvgs, bar_index - 1, low[2], high, false, bearColorInput, \"FVG\", fvgCountInput)\n\n// Zone lifecycle (runs every bar; a zone created on this bar is not tested until the next one).\nbool obCloseMode = obMitigInput == \"Close\"\nbool bullObGone = false\nbool bearObGone = false\nif barstate.isconfirmed\n    bullObGone := updateZones(bullObs, obCloseMode)\n    bearObGone := updateZones(bearObs, obCloseMode)\n    updateZones(bullFvgs, true)\n    updateZones(bearFvgs, true)\n\n// ---------- Bias table ----------\nvar table dash = table.new(position.top_right, 2, 2, border_width = 1, border_color = color.new(color.gray, 70))\nif showDashInput and barstate.islast\n    table.cell(dash, 0, 0, \"Swing\", text_color = color.gray, text_size = size.small, bgcolor = color.new(color.gray, 90))\n    table.cell(dash, 1, 0, swingTrend == 1 ? \"Bullish\" : swingTrend == -1 ? \"Bearish\" : \"-\", text_color = color.white, text_size = size.small, bgcolor = color.new(swingTrend == 1 ? bullColorInput : swingTrend == -1 ? bearColorInput : color.gray, 30))\n    table.cell(dash, 0, 1, \"Internal\", text_color = color.gray, text_size = size.small, bgcolor = color.new(color.gray, 90))\n    table.cell(dash, 1, 1, internalTrend == 1 ? \"Bullish\" : internalTrend == -1 ? \"Bearish\" : \"-\", text_color = color.white, text_size = size.small, bgcolor = color.new(internalTrend == 1 ? bullColorInput : internalTrend == -1 ? bearColorInput : color.gray, 30))\n\n// ---------- Alerts ----------\nalertcondition(sBullBos,   \"Bullish BOS\",   \"Nexus SMC: bullish BOS on {{ticker}} {{interval}} at {{close}}\")\nalertcondition(sBearBos,   \"Bearish BOS\",   \"Nexus SMC: bearish BOS on {{ticker}} {{interval}} at {{close}}\")\nalertcondition(sBullChoch, \"Bullish CHoCH\", \"Nexus SMC: bullish CHoCH on {{ticker}} {{interval}} at {{close}}\")\nalertcondition(sBearChoch, \"Bearish CHoCH\", \"Nexus SMC: bearish CHoCH on {{ticker}} {{interval}} at {{close}}\")\nalertcondition(iBullBos or iBullChoch, \"Internal bullish break\", \"Nexus SMC: internal bullish break on {{ticker}} {{interval}}\")\nalertcondition(iBearBos or iBearChoch, \"Internal bearish break\", \"Nexus SMC: internal bearish break on {{ticker}} {{interval}}\")\nalertcondition(bullFvg,    \"Bullish FVG\",   \"Nexus SMC: bullish FVG on {{ticker}} {{interval}}\")\nalertcondition(bearFvg,    \"Bearish FVG\",   \"Nexus SMC: bearish FVG on {{ticker}} {{interval}}\")\nalertcondition(bullObGone, \"Bullish order block mitigated\", \"Nexus SMC: bullish order block mitigated on {{ticker}} {{interval}}\")\nalertcondition(bearObGone, \"Bearish order block mitigated\", \"Nexus SMC: bearish order block mitigated on {{ticker}} {{interval}}\")\nalertcondition(sweepHigh,  \"Buy-side liquidity sweep\",  \"Nexus SMC: sweep above swing high on {{ticker}} {{interval}}\")\nalertcondition(sweepLow,   \"Sell-side liquidity sweep\", \"Nexus SMC: sweep below swing low on {{ticker}} {{interval}}\")\nalertcondition(eqHigh or eqLow, \"Equal highs / lows\", \"Nexus SMC: equal highs/lows on {{ticker}} {{interval}}\")\n"
